function [j, status] = utc2tai(jd_utc)
%UTC2TAI  UTC to TAI, TAI to UTC (the leap looked up on the TAI date, as MATLAB), TAI to TT and back, TT to UTC, UTC to TT; each
%   that looks the leap up gives its status.
%   jd_utc: real[1] (passed a plain number)
%   returns j: real[1] (passed a plain number)
%   returns status: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    j = 0;
    status = 0;
    [n, st] = asils.models.timescales.tai_minus_utc(jd_utc);
    j = (jd_utc + (n / 86400));
    status = st;
end
